import numpy as np


class Normalizer:
    def __init__(self):
        self.mean = {}
        self.std = {}
        self.min_val = {}
        self.max_val = {}

    def fit(self, data: dict, variable_groups: dict):
        for name, arr in data.items():
            if name in variable_groups.get("static", []):
                self.min_val[name] = arr.min()
                self.max_val[name] = arr.max()
            else:
                self.mean[name] = arr.mean()
                self.std[name] = arr.std()

    def normalize(self, name: str, arr: torch.Tensor) -> torch.Tensor:
        if name in self.min_val:
            mn, mx = self.min_val[name], self.max_val[name]
            return (arr - mn) / (mx - mn + 1e-8)
        return (arr - self.mean[name]) / (self.std[name] + 1e-8)

    def denormalize(self, name: str, arr: torch.Tensor) -> torch.Tensor:
        if name in self.min_val:
            mn, mx = self.min_val[name], self.max_val[name]
            return arr * (mx - mn) + mn
        return arr * self.std[name] + self.mean[name]

    def state_dict(self) -> dict:
        return {"mean": self.mean, "std": self.std, "min": self.min_val, "max": self.max_val}

    def load_state_dict(self, state: dict):
        self.mean = state.get("mean", {})
        self.std = state.get("std", {})
        self.min_val = state.get("min", {})
        self.max_val = state.get("max", {})
